export const cinematicHairFragment = "precision highp float;\n\nuniform float uTime;\nuniform float uScrollProgress;\nuniform float uCutProgress;\nuniform float uColorProgress;\nuniform float uTreatmentProgress;\nuniform float uStyleProgress;\nuniform float uWaveStrength;\nuniform float uFinalProgress;\nuniform vec3 uKeyColor;\nuniform vec3 uRimColor;\nuniform vec3 uColor0;\nuniform vec3 uColor1;\nuniform vec3 uColor2;\nuniform vec3 uColor3;\nuniform vec3 uHighlight0;\nuniform vec3 uHighlight1;\nuniform vec3 uHighlight2;\nuniform vec3 uHighlight3;\nuniform float uQuality;\n\nvarying vec2 vUv;\nvarying vec3 vNormal;\nvarying vec3 vViewDirection;\nvarying float vCutMask;\nvarying float vEdge;\n\nvec3 journeyHairColor(float progress) {\n  float stage = clamp(progress, 0.0, 1.0) * 3.0;\n  if (stage < 1.0) return mix(uColor0, uColor1, smoothstep(0.0, 1.0, stage));\n  if (stage < 2.0) return mix(uColor1, uColor2, smoothstep(1.0, 2.0, stage));\n  return mix(uColor2, uColor3, smoothstep(2.0, 3.0, stage));\n}\n\nvec3 journeyHairHighlight(float progress) {\n  float stage = clamp(progress, 0.0, 1.0) * 3.0;\n  if (stage < 1.0) return mix(uHighlight0, uHighlight1, smoothstep(0.0, 1.0, stage));\n  if (stage < 2.0) return mix(uHighlight1, uHighlight2, smoothstep(1.0, 2.0, stage));\n  return mix(uHighlight2, uHighlight3, smoothstep(2.0, 3.0, stage));\n}\n\nvoid main() {\n  if (vCutMask < 0.012) discard;\n\n  vec3 normal = normalize(vNormal);\n  vec3 viewDirection = normalize(vViewDirection);\n  vec3 keyDirection = normalize(vec3(-0.42, 0.34, 0.84));\n  vec3 rimDirection = normalize(vec3(0.74, 0.2, 0.64));\n  vec3 halfDirection = normalize(keyDirection + viewDirection);\n  float key = max(dot(normal, keyDirection), 0.0);\n  float fill = max(dot(normal, normalize(vec3(0.5, -0.4, 0.72))), 0.0);\n  float fresnel = pow(1.0 - max(dot(normal, viewDirection), 0.0), 2.7);\n  float rim = pow(max(dot(normal, rimDirection), 0.0), 3.0) + fresnel * 0.7;\n\n  float gloss = mix(0.25, 0.9, uTreatmentProgress);\n  float specularPower = mix(22.0, 76.0, uTreatmentProgress);\n  float specular = pow(max(dot(normal, halfDirection), 0.0), specularPower);\n  // Fine longitudinal fibres and one travelling satin lobe keep the surface\n  // reading as a lock of hair rather than a flat metallic strip.\n  float strand = sin(\n    vUv.x * 260.0 + vUv.y * 9.0 + sin(vUv.y * 31.0) * 1.7\n  );\n  strand = strand * 0.5 + 0.5;\n  float strandDetail = mix(0.018, 0.052, uQuality) * strand;\n  float highlightCenter = 0.42\n    + sin(vUv.y * 7.0 - uTime * 0.16) * (0.035 + uStyleProgress * 0.035);\n  float silkLobe = exp(-pow((vUv.x - highlightCenter) * 5.8, 2.0));\n\n  vec3 base = journeyHairColor(uColorProgress);\n  vec3 hairHighlight = journeyHairHighlight(uColorProgress);\n  vec3 color = base * (0.58 + key * 0.66 + fill * 0.18);\n  color += mix(base, hairHighlight, 0.44) * strandDetail;\n  color += hairHighlight * silkLobe * (0.025 + uTreatmentProgress * 0.045);\n  color += mix(uKeyColor, hairHighlight, 0.42) * specular * (0.12 + gloss * 0.34);\n  color += mix(uRimColor, hairHighlight, 0.28) * rim * (0.07 + gloss * 0.13);\n\n  float sweepPosition = mix(-0.18, 1.18, uTreatmentProgress);\n  float lightSweep = exp(-pow((vUv.y - sweepPosition) * 10.5, 2.0));\n  lightSweep *= smoothstep(0.02, 0.2, uTreatmentProgress);\n  color += uKeyColor * lightSweep * (0.055 + gloss * 0.085);\n\n  float cutLine = mix(-0.015, 0.235, uCutProgress);\n  float cutEdge = exp(-pow((vUv.y - cutLine) * 95.0, 2.0));\n  color += vec3(0.58, 0.51, 0.45) * cutEdge * sin(uCutProgress * 3.14159265) * 0.12;\n\n  float silhouette = 1.0 - smoothstep(0.84, 1.0, vEdge) * 0.34;\n  float finalFade = 1.0 - smoothstep(0.06, 0.38, uFinalProgress);\n  float alpha = vCutMask * silhouette * finalFade;\n  gl_FragColor = vec4(color, alpha);\n  #include <colorspace_fragment>\n}\n";
export const hairJourneyParticleVertex = "precision highp float;\n\nuniform float uTime;\nuniform float uCutProgress;\nuniform float uPointSize;\nuniform float uDpr;\n\nattribute vec4 aRandom;\nvarying float vAlpha;\nvarying float vWarmth;\n\nvoid main() {\n  float burst = sin(clamp(uCutProgress, 0.0, 1.0) * 3.14159265);\n  float cutY = mix(-1.7, -0.9, uCutProgress);\n  float angle = aRandom.x * 6.2831853;\n  float distanceTravelled = pow(uCutProgress, 0.72) * mix(0.08, 0.34, aRandom.y);\n  vec3 transformed = vec3(\n    (aRandom.z - 0.5) * 0.38,\n    cutY,\n    (aRandom.w - 0.5) * 0.12\n  );\n  transformed.x += cos(angle) * distanceTravelled;\n  transformed.y += sin(angle) * distanceTravelled * 0.38 - distanceTravelled * 0.1;\n  transformed.x += sin(uTime * (0.7 + aRandom.y) + aRandom.w * 9.0) * 0.015 * burst;\n\n  vec4 viewPosition = modelViewMatrix * vec4(transformed, 1.0);\n  gl_Position = projectionMatrix * viewPosition;\n  gl_PointSize = uPointSize * uDpr * mix(0.65, 1.1, aRandom.z);\n  vAlpha = burst * mix(0.2, 0.52, aRandom.y);\n  vWarmth = aRandom.w;\n}\n";
export const hairJourneyParticleFragment = "precision highp float;\n\nvarying float vAlpha;\nvarying float vWarmth;\n\nvoid main() {\n  float distanceFromCenter = length(gl_PointCoord - 0.5);\n  float core = 1.0 - smoothstep(0.08, 0.48, distanceFromCenter);\n  vec3 cool = vec3(0.56, 0.58, 0.62);\n  vec3 warm = vec3(0.71, 0.61, 0.48);\n  gl_FragColor = vec4(mix(cool, warm, vWarmth) * (0.55 + core * 0.45), core * vAlpha);\n  #include <colorspace_fragment>\n}\n";
export const hairJourneyThreadsVertex = "precision highp float;\n\nuniform float uTime;\nuniform float uFinalProgress;\nuniform vec2 uMouse;\nuniform vec2 uFrameScale;\nuniform float uQuality;\n\nattribute float aRibbonIndex;\nattribute vec4 aRandom;\nattribute float aBandUv;\n\nvarying vec2 vUv;\nvarying float vBandUv;\nvarying float vUnwoven;\nvarying float vRandom;\nvarying float vOpacity;\n\nvoid main() {\n  vUv = uv;\n  vBandUv = aBandUv;\n  vRandom = aRandom.x;\n\n  float progress = clamp(uFinalProgress, 0.0, 1.0);\n  float birth = smoothstep(0.015, 0.2, progress);\n  float spread = smoothstep(0.05, 0.4, progress);\n  float settle = smoothstep(0.48, 0.96, progress);\n  float unwoven = sin(smoothstep(0.0, 1.0, progress) * 3.14159265);\n  unwoven *= 1.0 - settle * 0.72;\n  vUnwoven = unwoven;\n  vOpacity = birth;\n\n  vec2 transformed = position.xy;\n  vec2 collapsedScale = vec2(0.095, 0.72);\n  transformed *= mix(collapsedScale, uFrameScale, spread);\n\n  float outerRibbon = abs(aRibbonIndex * 2.0 - 1.0);\n  float edgeMotion = 0.28 + pow(outerRibbon, 1.4) * 0.72;\n  float phase = aRandom.x * 14.0 + aRibbonIndex * 10.0;\n  float primaryWave = sin(position.x * mix(5.0, 9.0, aRandom.y) + phase + uTime * 0.42);\n  float fineWave = sin(position.x * 17.0 - uTime * 0.25 + phase * 0.7);\n  transformed.y += (primaryWave * 0.052 + fineWave * 0.014) * unwoven * edgeMotion * uQuality;\n  transformed.x += (aRandom.z - 0.5) * 0.1 * unwoven * edgeMotion;\n  transformed.y += (aRandom.y - 0.5) * 0.065 * unwoven;\n  transformed.x += uMouse.x * 0.018 * unwoven;\n  transformed.y += uMouse.y * 0.012 * unwoven * edgeMotion;\n\n  gl_Position = vec4(transformed, 0.0, 1.0);\n}\n";
export const hairJourneyThreadsFragment = "precision highp float;\n\nuniform sampler2D uTexture;\nuniform float uQuality;\n\nvarying vec2 vUv;\nvarying float vBandUv;\nvarying float vUnwoven;\nvarying float vRandom;\nvarying float vOpacity;\n\nvoid main() {\n  float shift = vUnwoven * mix(0.00025, 0.001, uQuality) * (0.7 + vRandom * 0.3);\n  vec4 source = texture2D(uTexture, vUv);\n  vec3 color = vec3(\n    texture2D(uTexture, vUv + vec2(shift, 0.0)).r,\n    source.g,\n    texture2D(uTexture, vUv - vec2(shift, 0.0)).b\n  );\n\n  float bandDistance = min(vBandUv, 1.0 - vBandUv) * 2.0;\n  float bandEdge = 1.0 - smoothstep(0.0, 0.18, bandDistance);\n  color += vec3(0.78, 0.8, 0.84) * bandEdge * vUnwoven * 0.035;\n  float ribbonFade = mix(1.0, smoothstep(0.0, 0.12, bandDistance), vUnwoven * 0.5);\n  float photoEdge = smoothstep(0.0, 0.018, vUv.x) * smoothstep(0.0, 0.018, 1.0 - vUv.x);\n  float alpha = source.a * vOpacity * ribbonFade * photoEdge;\n\n  gl_FragColor = vec4(color, alpha);\n  #include <colorspace_fragment>\n}\n";
export const particleVertex = "attribute vec3 randomPosition;\nattribute vec3 targetPosition;\nattribute vec3 sampleColor;\nuniform float uProgress;\nuniform float uTime;\nuniform float uDpr;\nuniform float uPointSize;\nuniform vec4 uImageRect;\nvarying float vAlpha;\nvarying vec3 vColor;\nvarying float vEnergy;\nvoid main() {\n  vec2 targetUV = uImageRect.xy + targetPosition.xy * uImageRect.zw;\n  vec2 target = vec2(targetUV.x * 2.0 - 1.0, 1.0 - targetUV.y * 2.0);\n  float delay = randomPosition.z * .13 + targetPosition.y * .035;\n  float progress = smoothstep(0.0, 1.0, clamp((uProgress - delay) / .84, 0.0, 1.0));\n  float inverse = 1.0 - progress;\n  float side = sign(randomPosition.x);\n  vec2 control = mix(randomPosition.xy, target, .5);\n  control += vec2(-side * (.2 + randomPosition.z * .22), (randomPosition.z - .5) * .62);\n  vec2 p = inverse * inverse * randomPosition.xy + 2.0 * inverse * progress * control + progress * progress * target;\n  vec2 tangent = normalize(vec2(-(target.y - control.y), target.x - control.x) + vec2(.001));\n  float curl = sin(progress * 3.14159) * (.055 + randomPosition.z * .07);\n  p += tangent * curl * sin(uTime * 2.4 + randomPosition.z * 24.0 + target.y * 5.0);\n  p += (randomPosition.z - .5) * vec2(.07, .035) * inverse;\n  float lockPulse = exp(-pow((uTime - 1.82) * 6.0, 2.0));\n  gl_Position = vec4(p, (randomPosition.z - .5) * .12 * inverse, 1.0);\n  gl_PointSize = uPointSize * uDpr * (.58 + randomPosition.z * .35 + lockPulse * .42);\n  vAlpha = .56 + targetPosition.z * .36;\n  vEnergy = sin(progress * 3.14159) * .42 + lockPulse;\n  vec3 noirBlue = mix(vec3(.24, .38, .68), vec3(.68, .55, .9), randomPosition.z);\n  float sourceMix = smoothstep(.72, 1.0, progress);\n  vColor = mix(noirBlue, sampleColor * 1.28 + vec3(.035), sourceMix);\n}\n";
export const particleFragment = "uniform float uOpacity;\nvarying float vAlpha;\nvarying vec3 vColor;\nvarying float vEnergy;\nvoid main() {\n  float distanceToCenter = length(gl_PointCoord - .5);\n  float halo = (1.0 - smoothstep(.12, .5, distanceToCenter)) * .3;\n  float core = 1.0 - smoothstep(.025, .16, distanceToCenter);\n  float alpha = (halo + core * .8) * vAlpha * uOpacity;\n  gl_FragColor = vec4(vColor * (.86 + core * .72 + vEnergy * .42), alpha);\n  #include <colorspace_fragment>\n}\n";
